const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),a=require('node:assert/strict');const root=path.resolve(__dirname,'..'),out=path.join(root,'qa/career-page-review-20261116');let browser;const server=http.createServer((req,res)=>{const file=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname.replace(/^\/$/,'/index.html'));if(!file.startsWith(root+'/'))return res.end();fs.readFile(file,(e,b)=>{res.statusCode=e?404:200;res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css','.webp':'image/webp','.ttf':'font/ttf'})[path.extname(file)]||'application/octet-stream');res.end(e?'missing':b);});});
(async()=>{const report={scope:'Local isolated Chromium touchscreen slot947, not production or real phone',errors:[],steps:[]};try{await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true,reducedMotion:'reduce'}),p=await context.newPage();p.on('pageerror',e=>report.errors.push(e.message));await p.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});await p.locator('#enterGame').click();await p.evaluate(()=>{slot=947;$('job').value='barista';$('start').click();clearModals();state.housing='family';state.housingCost=500;state.housingLease={key:'family',monthly:500,depositHeld:0,startMonth:0};state.monthlyPayments={month:state.month,housing:500,living:800,premiums:0};state.homeArrival={fromMonth:-1,targetMonth:0,status:'completed'};save();openGame();clearModals();openRoom();});await p.evaluate(()=>CareerPages.career());await p.getByRole('button',{name:'查看其他工作机会',exact:true}).click();await p.screenshot({path:path.join(out,'local-career-market-390.png'),fullPage:false});a.equal(await p.locator('[data-batch=applyCareer]').count(),0);a.match(await p.locator('.career-overlay').innerText(),/暂时没有新的工作机会/);await p.evaluate(()=>CareerPages.career());await p.getByRole('button',{name:'申请辞职',exact:true}).click();await p.locator('.career-scene img').evaluate(i=>i.decode());await p.screenshot({path:path.join(out,'local-work-adjustment-390.png'),fullPage:false});a.equal(await p.getByRole('button',{name:'确认辞职',exact:true}).count(),1);console.log('Empty opportunities and direct resignation confirmation verified');a.deepEqual(report.errors,[]);}finally{await browser?.close();server.close();}})();